    `bridgeMode=${input.bridgeResult.bridgeMode}`,
    `providerHealth=${input.providerHealthStatus ?? 'unknown'}`,
    `endpointStatus=${input.endpointStatus ?? 'unknown'}`,
    `sessionCount=${String(input.sessionCount ?? 0)}`,
    ...input.runtimeSignals,
  ]);

